import React, { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';

interface SystemHealthStatus {
  overall: 'healthy' | 'warning' | 'critical';
  i18n: {
    status: 'loaded' | 'loading' | 'error';
    currentLanguage: string;
    error?: string;
  };
  auth: {
    status: 'authenticated' | 'unauthenticated' | 'loading' | 'error';
    sessionValid: boolean;
    error?: string;
  };
  api: {
    status: 'connected' | 'disconnected' | 'error';
    responseTime?: number;
    error?: string;
  };
  websocket: {
    status: 'connected' | 'disconnected' | 'connecting' | 'error';
    error?: string;
  };
}

interface SystemHealthCheckProps {
  onHealthChange?: (status: SystemHealthStatus) => void;
  showDetails?: boolean;
  className?: string;
}

export const SystemHealthCheck: React.FC<SystemHealthCheckProps> = ({
  onHealthChange,
  showDetails = false,
  className = '',
}) => {
  const { t, i18n } = useTranslation();
  const [healthStatus, setHealthStatus] = useState<SystemHealthStatus>({
    overall: 'loading' as any,
    i18n: {
      status: 'loading',
      currentLanguage: i18n.language,
    },
    auth: {
      status: 'loading',
      sessionValid: false,
    },
    api: {
      status: 'disconnected',
    },
    websocket: {
      status: 'disconnected',
    },
  });

  const [isVisible, setIsVisible] = useState(false);

  // Перевірка стану i18n
  const checkI18nHealth = useCallback(() => {
    try {
      const testTranslation = t('common.loading');
      const isLoaded = i18n.isInitialized && testTranslation !== 'common.loading';

      return {
        status: isLoaded ? 'loaded' as const : 'loading' as const,
        currentLanguage: i18n.language,
      };
    } catch (error) {
      return {
        status: 'error' as const,
        currentLanguage: i18n.language,
        error: error instanceof Error ? error.message : 'Unknown i18n error',
      };
    }
  }, [t, i18n]);

  // Перевірка стану авторизації
  const checkAuthHealth = useCallback(async () => {
    try {
      const sessionId = localStorage.getItem('sessionId');
      if (!sessionId) {
        return {
          status: 'unauthenticated' as const,
          sessionValid: false,
        };
      }

      const response = await fetch('/api/auth/validate', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ sessionId }),
      });

      if (response.ok) {
        const data = await response.json();
        return {
          status: 'authenticated' as const,
          sessionValid: data.valid,
        };
      } else {
        return {
          status: 'error' as const,
          sessionValid: false,
          error: `HTTP ${response.status}`,
        };
      }
    } catch (error) {
      return {
        status: 'error' as const,
        sessionValid: false,
        error: error instanceof Error ? error.message : 'Unknown auth error',
      };
    }
  }, []);

  // Перевірка стану API
  const checkApiHealth = useCallback(async () => {
    try {
      const startTime = Date.now();
      const response = await fetch('/api/health', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      const responseTime = Date.now() - startTime;

      if (response.ok) {
        return {
          status: 'connected' as const,
          responseTime,
        };
      } else {
        return {
          status: 'error' as const,
          responseTime,
          error: `HTTP ${response.status}`,
        };
      }
    } catch (error) {
      return {
        status: 'error' as const,
        error: error instanceof Error ? error.message : 'Unknown API error',
      };
    }
  }, []);

  // Перевірка стану WebSocket
  const checkWebSocketHealth = useCallback(() => {
    try {
      // Перевіряємо, чи є активне WebSocket з'єднання
      const wsUrl = `ws://${window.location.host}/ws`;
      const testWs = new WebSocket(wsUrl);

      return new Promise<{
        status: 'connected' | 'disconnected' | 'error';
        error?: string;
      }>((resolve) => {
        const timeout = setTimeout(() => {
          testWs.close();
          resolve({
            status: 'disconnected',
            error: 'Connection timeout',
          });
        }, 3000);

        testWs.onopen = () => {
          clearTimeout(timeout);
          testWs.close();
          resolve({
            status: 'connected',
          });
        };

        testWs.onerror = (error) => {
          clearTimeout(timeout);
          resolve({
            status: 'error',
            error: 'WebSocket connection failed',
          });
        };

        testWs.onclose = () => {
          clearTimeout(timeout);
          resolve({
            status: 'disconnected',
          });
        };
      });
    } catch (error) {
      return Promise.resolve({
        status: 'error' as const,
        error: error instanceof Error ? error.message : 'Unknown WebSocket error',
      });
    }
  }, []);

  // Визначення загального стану системи
  const calculateOverallHealth = useCallback((status: Omit<SystemHealthStatus, 'overall'>) => {
    const criticalErrors = [
      status.i18n.status === 'error',
      status.auth.status === 'error',
      status.api.status === 'error',
      status.websocket.status === 'error',
    ].filter(Boolean).length;

    const warnings = [
      status.i18n.status === 'loading',
      status.auth.status === 'loading',
      status.api.status === 'disconnected',
      status.websocket.status === 'disconnected',
    ].filter(Boolean).length;

    if (criticalErrors > 0) {
      return 'critical' as const;
    } else if (warnings > 0) {
      return 'warning' as const;
    } else {
      return 'healthy' as const;
    }
  }, []);

  // Основна функція перевірки здоров'я системи
  const performHealthCheck = useCallback(async () => {
    try {
      const i18nHealth = checkI18nHealth();
      const authHealth = await checkAuthHealth();
      const apiHealth = await checkApiHealth();
      const wsHealth = await checkWebSocketHealth();

      const newStatus = {
        i18n: i18nHealth,
        auth: authHealth,
        api: apiHealth,
        websocket: wsHealth,
        overall: 'healthy' as const,
      };

      newStatus.overall = calculateOverallHealth(newStatus);

      setHealthStatus(newStatus);
      onHealthChange?.(newStatus);

      // Показуємо компонент тільки якщо є проблеми
      setIsVisible(newStatus.overall !== 'healthy');
    } catch (error) {
      console.error('Health check failed:', error);
    }
  }, [checkI18nHealth, checkAuthHealth, checkApiHealth, checkWebSocketHealth, calculateOverallHealth, onHealthChange]);

  // Запуск перевірки при завантаженні та періодично
  useEffect(() => {
    performHealthCheck();
    const interval = setInterval(performHealthCheck, 30000); // Кожні 30 секунд
    return () => clearInterval(interval);
  }, [performHealthCheck]);

  // Якщо компонент не видимий, не рендеримо його
  if (!isVisible && !showDetails) {
    return null;
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'healthy':
      case 'loaded':
      case 'authenticated':
      case 'connected':
        return 'text-green-600';
      case 'warning':
      case 'loading':
      case 'connecting':
        return 'text-yellow-600';
      case 'critical':
      case 'error':
      case 'disconnected':
        return 'text-red-600';
      default:
        return 'text-gray-600';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'healthy':
      case 'loaded':
      case 'authenticated':
      case 'connected':
        return '✅';
      case 'warning':
      case 'loading':
      case 'connecting':
        return '⚠️';
      case 'critical':
      case 'error':
      case 'disconnected':
        return '❌';
      default:
        return '🔄';
    }
  };

  return (
    <div className={`system-health-check ${className}`}>
      {/* Компактний вигляд */}
      {!showDetails && (
        <div className="flex items-center space-x-2 bg-white/10 backdrop-blur-md rounded-lg px-3 py-2 border border-white/20">
          <span className="text-lg">{getStatusIcon(healthStatus.overall)}</span>
          <span className={`text-sm font-medium ${getStatusColor(healthStatus.overall)}`}>
            {t(`common.${healthStatus.overall}`)}
          </span>
        </div>
      )}

      {/* Детальний вигляд */}
      {showDetails && (
        <div className="bg-white/10 backdrop-blur-md rounded-xl p-4 border border-white/20">
          <h3 className="text-lg font-semibold text-white mb-4">
            {t('dashboard.systemHealth')}
          </h3>

          <div className="space-y-3">
            {/* Загальний стан */}
            <div className="flex items-center justify-between">
              <span className="text-white/80">Overall Status</span>
              <div className="flex items-center space-x-2">
                <span>{getStatusIcon(healthStatus.overall)}</span>
                <span className={`font-medium ${getStatusColor(healthStatus.overall)}`}>
                  {healthStatus.overall}
                </span>
              </div>
            </div>

            {/* i18n */}
            <div className="flex items-center justify-between">
              <span className="text-white/80">Localization</span>
              <div className="flex items-center space-x-2">
                <span>{getStatusIcon(healthStatus.i18n.status)}</span>
                <span className={`font-medium ${getStatusColor(healthStatus.i18n.status)}`}>
                  {healthStatus.i18n.status} ({healthStatus.i18n.currentLanguage})
                </span>
              </div>
            </div>

            {/* Auth */}
            <div className="flex items-center justify-between">
              <span className="text-white/80">Authentication</span>
              <div className="flex items-center space-x-2">
                <span>{getStatusIcon(healthStatus.auth.status)}</span>
                <span className={`font-medium ${getStatusColor(healthStatus.auth.status)}`}>
                  {healthStatus.auth.status}
                </span>
              </div>
            </div>

            {/* API */}
            <div className="flex items-center justify-between">
              <span className="text-white/80">API Connection</span>
              <div className="flex items-center space-x-2">
                <span>{getStatusIcon(healthStatus.api.status)}</span>
                <span className={`font-medium ${getStatusColor(healthStatus.api.status)}`}>
                  {healthStatus.api.status}
                  {healthStatus.api.responseTime && (
                    <span className="text-xs text-white/60 ml-1">
                      ({healthStatus.api.responseTime}ms)
                    </span>
                  )}
                </span>
              </div>
            </div>

            {/* WebSocket */}
            <div className="flex items-center justify-between">
              <span className="text-white/80">WebSocket</span>
              <div className="flex items-center space-x-2">
                <span>{getStatusIcon(healthStatus.websocket.status)}</span>
                <span className={`font-medium ${getStatusColor(healthStatus.websocket.status)}`}>
                  {healthStatus.websocket.status}
                </span>
              </div>
            </div>

            {/* Кнопка оновлення */}
            <div className="mt-4 pt-3 border-t border-white/20">
              <button
                onClick={performHealthCheck}
                className="w-full py-2 px-4 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors duration-200 text-sm font-medium"
              >
                {t('common.refresh')}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
